    vector<long long> second(M);
    for (int i = 0; i < M; ++i) {
        cin >> second[i];
    }

    int max_length = 0;

    // Try all possible lengths of the subsequence
    for (int length = 1; length <= min(N, M); ++length) {
        vector<long long> hashes_first;
        for (int i = 0; i <= N - length; ++i) {
            hashes_first.push_back(hash_value(first, i, i + length - 1));
        }

        vector<long long> hashes_second;
        for (int i = 0; i <= M - length; ++i) {
            hashes_second.push_back(hash_value(second, i, i + length - 1));
        }

        // Check if any hash in hashes_first matches any hash in hashes_second
        bool found = false;
        for (long long h : hashes_first) {
            if (find(hashes_second.begin(), hashes_second.end(), h) != hashes_second.end()) {
                found = true;
                break;
            }
