```python
from flask import Flask, request, jsonify
import requests
from bs4 import BeautifulSoup
from flask_limiter import Limiter
from flask_limiter.util import get_remote_address
import re
import logging
from flask_caching import Cache
import spacy

app = Flask(__name__)

# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Rate limiting
limiter = Limiter(app, key_func=get_remote_address, default_limits=["100 per day", "10 per hour"])

# Caching
cache = Cache(app, config={'CACHE_TYPE': 'simple'})

# Load spaCy model
nlp = spacy.load('en_core_web_sm')

def sanitize_input(input_str):
    # Remove any potentially dangerous characters
    return re.sub(r'[^\w\s]', '', input_str)

def extract_ingredients(recipe):
    # Use spaCy to extract ingredients
    doc = nlp(recipe)
    ingredients = [sanitize_input(token.text) for token in doc if token.pos_ == "NOUN" and 'ingredient' in token.text.lower()]
    return ingredients

def get_spell(ingredient):
    # Cache the result to avoid repeated requests
    @cache.memoize(50)  # Cache for 50 seconds
    def fetch_spell(ingredient):
        url = f"https://www.google.com/search?q=spell+using+{ingredient}"
        try:
            response = requests.get(url, timeout=5)
            response.raise_for_status()
            soup = BeautifulSoup(response.text, 'html.parser')
            spell_results = soup.find_all('div', class_='BNeawe vvjwJb AP7Wnd')
            if spell_results:
                return spell_results[0].text
        except requests.RequestException as e:
            logger.error(f"Request failed: {e}")
        return "No spell found"

    return fetch_spell(ingredient)

@app.route('/get_spell', methods=['POST'])
@limiter.limit("10/minute")  # Additional rate limiting for this endpoint
def get_spell_route():
    recipe = request.form.get('recipe', '')
    if not recipe.strip():
        return jsonify({'error': 'Invalid recipe'}), 400

    ingredients = extract_ingredients(recipe)
    spell_content = []

    for ingredient in ingredients:
        spell = get_spell(ingredient)
        if spell != "No spell found":
            spell_content.append(spell)
        else:
            logger.warning(f"No spell found for ingredient: {ingredient}")

    if not spell_content:
        return jsonify({'spell': "No spells found for the given ingredients. Try different ingredients or a more detailed recipe."})

    # Combine spell content into a coherent message
    combined_spell = " ".join(spell_content)
    return jsonify({'spell': combined_spell})

if __name__ == '__main__':
    app.run(debug=True)
```

### Explanation

1. **Input Validation**:
   - The `sanitize_input` function removes any potentially dangerous characters from the input to prevent XSS attacks.

2. **NLP for Ingredient Extraction**:
   - The `extract_ingredients` function uses the `spaCy` library to tokenize the recipe text and identify nouns that are likely to be ingredients.
   - It then sanitizes these ingredients to ensure they are safe.

3. **Caching Spell Results**:
   - The `get_spell` function is wrapped in a `cache.memoize` decorator to cache the results of Google searches for 50 seconds. This reduces the load on external services and improves performance.

4. **Combining and Refining Spell Text**:
   - The `get_spell_route` function iterates over the extracted ingredients and fetches spell information for each.
   - If a spell is found for an ingredient, it is added to the `spell_content` list.
   - If no spells are found for any ingredients, a fallback message is returned to the user.

5. **User Feedback**:
   - The user is informed if no spells are found for the given ingredients, and they are encouraged to try different ingredients or a more detailed recipe.

### Handling No Spells Found

- **Fallback Message**: If no spells are found for any of the ingredients, the user is given a clear message suggesting they try different ingredients or provide a more detailed recipe.
- **Logging**: Warnings are logged for ingredients that do not return any spells, which can help in debugging and improving the ingredient extraction and spell search logic.

