public class EntityGeometry
{
    // Example properties for EntityGeometry
    public string Type { get; set; }
    public double[] Points { get; set; }

    // Method to convert EntityGeometry to a drawable form
    public Entity ToDrawable()
    {
        switch (Type.ToLower())
        {
            case "line":
                return new Line(new Point3d(Points[0], Points[1], 0), new Point3d(Points[2], Points[3], 0));
            case "circle":
                return new Circle(new Point3d(Points[0], Points[1], 0), Points[2]);
            default:
                throw new ArgumentException("Unsupported geometry type: " + Type);
        }
    }
}

public class TableDrawer
{
    /// <summary>
    /// Embeds a list of geometric entities into a specified cell of an McTable.
    /// </summary>
    /// <param name="entityGeometry">List of EntityGeometry objects representing the geometric entities to be embedded.</param>
    /// <param name="table">The McTable object where the entities will be embedded.</param>
    /// <param name="row">The row index of the cell where the entities will be embedded.</param>
    /// <param name="column">The column index of the cell where the entities will be embedded.</param>
    /// <exception cref="ArgumentNullException">Thrown if the table is null.</exception>
    /// <exception cref="ArgumentOutOfRangeException">Thrown if the row or column index is out of range.</exception>
    /// <exception cref="InvalidOperationException">Thrown if embedding fails and fallback mechanism is used.</exception>
    public void EmbedPrimitivesInTableCell(List<EntityGeometry> entityGeometry, McTable table, int row, int column)
    {
        if (table == null)
        {
            throw new ArgumentNullException(nameof(table), "Table cannot be null.");
        }

        if (row < 0 || row >= table.RowCount)
        {
            throw new ArgumentOutOfRangeException(nameof(row), "Row index is out of range.");
        }

        if (column < 0 || column >= table.ColumnCount)
        {
            throw new ArgumentOutOfRangeException(nameof(column), "Column index is out of range.");
        }

        // Create a block table record to hold all the drawable entities
        using (Transaction tr = HostApplicationServices.WorkingDatabase.TransactionManager.StartTransaction())
        {
            BlockTable blockTable = (BlockTable)tr.GetObject(HostApplicationServices.WorkingDatabase.BlockTableId, OpenMode.ForRead);
            BlockTableRecord blockRecord = new BlockTableRecord { Name = "EmbeddedBlock" };

            blockTable.UpgradeOpen();
            ObjectId blockRecordId = blockTable.Add(blockRecord);
            tr.AddNewlyCreatedDBObject(blockRecord, true);

            foreach (var entity in entityGeometry)
            {
                Entity drawable = entity.ToDrawable();
                if (drawable != null)
                {
                    blockRecord.AppendEntity(drawable);
                    tr.AddNewlyAutoId(drawable);
                }
            }

            // Create a block reference to the block table record
            BlockReference blockRef = new BlockReference(Point3d.Origin, blockRecordId);

            try
            {
                // Attempt to set the content of the specified cell to the block reference
                table.SetCellContent(row, column, blockRef);
            }
            catch (Exception ex)
            {
                // Fallback mechanism if SetCellContent does not support BlockReference
                Console.WriteLine($"Failed to set cell content with BlockReference: {ex.Message}");
                // Fallback: Serialize the block reference to a string and set it as cell content
                string blockRefString = SerializeBlockReference(blockRef);
                table.SetCellContent(row, column, blockRefString);
                throw new InvalidOperationException("Failed to embed primitives visually. Fallback mechanism used.", ex);
            }

            tr.Commit();
        }
    }

